1	import { Component, DestroyRef, computed, effect, inject, signal, untracked } from '@angular/core';
2	import {
3	  AbstractControl,
4	  FormControl,
5	  FormGroup,
6	  ReactiveFormsModule,
7	  ValidationErrors,
8	  ValidatorFn,
9	  Validators,
10	} from '@angular/forms';
11	import { Router } from '@angular/router';
12	import { CountryContentService } from '../../../core/services/country-content.service';
13	import { WizardStore } from '../../../core/state/wizard.store';
14	import type {
15	  FormFieldEntry,
16	  FormFieldType,
17	  FormFieldValue,
18	  Step1FormValue,
19	} from '../../../core/models/form-field.model';
20	
21	type Step1FormGroup = FormGroup<Record<string, FormControl<FormFieldValue>>>;
22	
23	function defaultValueFor(type: FormFieldType): FormFieldValue {
24	  switch (type) {
25	    case 'checkbox':
26	      return false;
27	    case 'number':
28	      return null;
29	    default:
30	      return '';
31	  }
32	}
33	
34	function legalAgeValidator(): ValidatorFn {
35	  return (control: AbstractControl<FormFieldValue>): ValidationErrors | null => {
36	    const value = control.value;
37	    if (value === null || value === '') {
38	      return null;
39	    }
40	
41	    const dateOfBirth = new Date(value as string);
42	    if (Number.isNaN(dateOfBirth.getTime())) {
43	      return { legalAge: true };
44	    }
45	
46	    const today = new Date();
47	    let age = today.getFullYear() - dateOfBirth.getFullYear();
48	    const birthdayPassedThisYear =
49	      today.getMonth() > dateOfBirth.getMonth() ||
50	      (today.getMonth() === dateOfBirth.getMonth() && today.getDate() >= dateOfBirth.getDate());
51	    if (!birthdayPassedThisYear) {
52	      age -= 1;
53	    }
54	
55	    return age >= 18 ? null : { legalAge: true };
56	  };
57	}
58	
59	function buildValidators(field: FormFieldEntry): ValidatorFn[] {
60	  const validators: ValidatorFn[] = [];
61	
62	  if (field.required) {
63	    validators.push(field.type === 'checkbox' ? Validators.requiredTrue : Validators.required);
64	  }
65	
66	  const validation = field.validation;
67	  if (validation?.min !== undefined) {
68	    validators.push(Validators.min(validation.min));
69	  }
70	  if (validation?.max !== undefined) {
71	    validators.push(Validators.max(validation.max));
72	  }
73	  if (validation?.minLength !== undefined) {
74	    validators.push(Validators.minLength(validation.minLength));
75	  }
76	  if (validation?.maxLength !== undefined) {
77	    validators.push(Validators.maxLength(validation.maxLength));
78	  }
79	  if (validation?.pattern) {
80	    validators.push(Validators.pattern(validation.pattern));
81	  }
82	
83	  if (field.key === 'dateOfBirth') {
84	    validators.push(legalAgeValidator());
85	  }
86	
87	  return validators;
88	}
89	
90	function buildStep1FormGroup(fields: FormFieldEntry[], existingValue: Step1FormValue): Step1FormGroup {
91	  const group = new FormGroup<Record<string, FormControl<FormFieldValue>>>({});
92	
93	  for (const field of fields) {
94	    const initialValue = existingValue[field.key] ?? defaultValueFor(field.type);
95	    group.addControl(
96	      field.key,
97	      new FormControl<FormFieldValue>(initialValue, { validators: buildValidators(field) }),
98	    );
99	  }
100	
101	  return group;
102	}
103	
104	@Component({
105	  selector: 'app-quote-form-page',
106	  imports: [ReactiveFormsModule],
107	  templateUrl: './quote-form-page.component.html',
108	  styleUrl: './quote-form-page.component.scss',
109	})
110	export class QuoteFormPageComponent {
111	  private readonly countryContentService = inject(CountryContentService);
112	  private readonly wizardStore = inject(WizardStore);
113	  private readonly router = inject(Router);
114	  private readonly destroyRef = inject(DestroyRef);
115	
116	  private readonly fieldsState = this.countryContentService.getFormFields();
117	
118	  readonly loading = computed(() => this.fieldsState().loading);
119	  readonly error = computed(() => this.fieldsState().error);
120	  readonly fields = computed(() => this.fieldsState().data ?? []);
121	
122	  readonly isEmpty = computed(() => {
123	    const state = this.fieldsState();
124	    return !state.loading && !state.error && state.data !== null && state.data.length === 0;
125	  });
126	
127	  readonly form = signal<Step1FormGroup | null>(null);
128	  readonly submitted = signal(false);
129	
130	  readonly hasAnyMisconfiguredSelect = computed(() =>
131	    this.fields().some((field) => this.hasMisconfiguredSelect(field)),
132	  );
133	
134	  private formSubscriptionCleanup: (() => void) | null = null;
135	
136	  constructor() {
137	    effect(() => {
138	      const state = this.fieldsState();
139	
140	      if (state.loading) {
141	        this.wizardStore.setStep1Status('loading');
142	        return;
143	      }
144	
145	      if (state.error) {
146	        this.wizardStore.setStep1Status('error');
147	        this.form.set(null);
148	        return;
149	      }
150	
151	      if (!state.data) {
152	        return;
153	      }
154	
155	      if (state.data.length === 0) {
156	        this.wizardStore.setStep1Status('empty');
157	        this.form.set(null);
158	        return;
159	      }
160	
161	      this.wizardStore.setStep1Status('ready');
162	      this.initializeForm(state.data);
163	    });
164	
165	    this.destroyRef.onDestroy(() => this.formSubscriptionCleanup?.());
166	  }
167	
168	  private initializeForm(fields: FormFieldEntry[]): void {
169	    const existingValue = untracked(() => this.wizardStore.state().step1.value);
170	    const group = buildStep1FormGroup(fields, existingValue);
171	
172	    if (Object.keys(existingValue).length > 0) {
173	      group.markAllAsTouched();
174	    }
175	
176	    this.formSubscriptionCleanup?.();
177	    const subscription = group.valueChanges.subscribe((value) => {
178	      this.wizardStore.setStep1Value(value as Step1FormValue);
179	    });
180	    this.formSubscriptionCleanup = () => subscription.unsubscribe();
181	
182	    this.wizardStore.setStep1Value(group.getRawValue());
183	    this.form.set(group);
184	  }
185	
186	  getControl(field: FormFieldEntry): FormControl<FormFieldValue> | undefined {
187	    return this.form()?.controls[field.key];
188	  }
