.quote-plans-page {
  max-width: 48rem;
  margin: 0 auto;
  padding: 1rem;

  &__status {
    padding: 1rem;
    border-radius: 0.5rem;
    background: #f5f5f5;

    &--error {
      background: #fdecea;
      color: #611a15;
    }
  }

  &__list {
    display: flex;
    flex-direction: column;
    gap: 1rem;
    margin-bottom: 1rem;
  }

  > button[type='button'] {
    padding: 0.6rem 1.25rem;
    border: none;
    border-radius: 0.25rem;
    background: #1a73e8;
    color: #fff;
    font-weight: 600;
    cursor: pointer;

    &:disabled {
      background: #a9c4ec;
      cursor: not-allowed;
    }

    &:focus-visible {
      outline: 2px solid #0d47a1;
      outline-offset: 2px;
    }
  }

  .quote-plans-page__status button[type='button'] {
    padding: 0.5rem 1rem;
    border: 1px solid #1a73e8;
    border-radius: 0.25rem;
    background: #fff;
    color: #1a73e8;
    cursor: pointer;
    margin-top: 0.5rem;

    &:focus-visible {
      outline: 2px solid #1a73e8;
      outline-offset: 2px;
    }
  }
}

.plan-card {
  position: relative;
  display: block;
  border: 1px solid #ccc;
  border-radius: 0.5rem;
  padding: 1rem;
  cursor: pointer;

  &--selected {
    border-color: #1a73e8;
    box-shadow: 0 0 0 1px #1a73e8;
  }

  &:focus-within {
    outline: 2px solid #1a73e8;
    outline-offset: 2px;
  }

  &__radio {
    position: absolute;
    width: 1px;
    height: 1px;
    opacity: 0;
  }

  &__header {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 0.5rem;
    margin-bottom: 0.25rem;
  }

  &__name {
    margin: 0;
    font-size: 1.1rem;
  }

  &__badge {
    font-size: 0.75rem;
    font-weight: 700;
    text-transform: uppercase;
    color: #0d5c2b;
    background: #e3f6e9;
    border: 1px solid #0d5c2b;
    border-radius: 999px;
    padding: 0.15rem 0.6rem;
  }

  &__description {
    color: #444;
    margin: 0 0 0.5rem;
  }

  &__price {
    font-size: 1.25rem;
    font-weight: 700;
    margin: 0 0 0.75rem;
  }

  &__section {
    margin-top: 0.5rem;

    h3 {
      font-size: 0.9rem;
      margin: 0 0 0.25rem;
    }

    ul {
      margin: 0;
      padding-left: 1.25rem;
    }

    li {
      font-size: 0.9rem;
      color: #333;
    }
  }
}

@media (max-width: 40rem) {
  .plan-card {
    padding: 0.75rem;
  }
}

